-- pdam.asset_index: read model for All-assets list, cross-type search and dashboard.
-- It is a projection: the typed collections remain the only source of truth.

CREATE TABLE IF NOT EXISTS asset_index (
  asset_id     uuid PRIMARY KEY,
  template     varchar(60) NOT NULL,
  name         text,
  status       varchar(32),
  provider_name text,
  account_name  text,
  expires_on   date,
  renewal_on   date,
  tags         text,
  search_text  text,
  updated_at   timestamptz NOT NULL DEFAULT now()
);
-- identity: one row per typed asset; (template, asset_id) is unique by contract
ALTER TABLE asset_index DROP CONSTRAINT IF EXISTS asset_index_identity_uk;
ALTER TABLE asset_index ADD CONSTRAINT asset_index_identity_uk UNIQUE (template, asset_id);
CREATE INDEX IF NOT EXISTS asset_index_template_idx ON asset_index (template);
CREATE INDEX IF NOT EXISTS asset_index_status_idx   ON asset_index (status);
CREATE INDEX IF NOT EXISTS asset_index_expires_idx  ON asset_index (expires_on);
CREATE INDEX IF NOT EXISTS asset_index_renewal_idx  ON asset_index (renewal_on);


-- accounts
CREATE OR REPLACE FUNCTION pdam_idx_accounts(p_id uuid) RETURNS void LANGUAGE plpgsql AS $fn$
DECLARE
  r accounts%ROWTYPE;
  v_tags text;
  v_provider text;
  v_account text;
  v_search text;
BEGIN
  SELECT * INTO r FROM accounts WHERE id = p_id;
  IF NOT FOUND THEN
    DELETE FROM asset_index WHERE asset_id = p_id;
    RETURN;
  END IF;

  SELECT string_agg(g.name, ', ' ORDER BY g.name) INTO v_tags
    FROM accounts_tags j JOIN tags g ON g.id = j.tags_id WHERE j.accounts_id = p_id;

  SELECT p.name INTO v_provider FROM providers p WHERE p.id = r.provider;

  v_account := NULL;

  v_search := lower(concat_ws(' ', r.name, v_provider, v_account, v_tags, r.username, r.email, r.url));

  INSERT INTO asset_index
    (asset_id, template, name, status, provider_name, account_name,
     expires_on, renewal_on, tags, search_text, updated_at)
  VALUES (r.id, 'accounts', r.name, r.status, v_provider, v_account,
          NULL::date, NULL::date, v_tags, v_search, now())
  ON CONFLICT (asset_id) DO UPDATE SET
    template = EXCLUDED.template, name = EXCLUDED.name, status = EXCLUDED.status,
    provider_name = EXCLUDED.provider_name, account_name = EXCLUDED.account_name,
    expires_on = EXCLUDED.expires_on, renewal_on = EXCLUDED.renewal_on,
    tags = EXCLUDED.tags, search_text = EXCLUDED.search_text, updated_at = now();
END $fn$;

CREATE OR REPLACE FUNCTION pdam_idx_trg_accounts() RETURNS trigger LANGUAGE plpgsql AS $t$
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM asset_index WHERE asset_id = OLD.id;
    RETURN OLD;
  END IF;
  PERFORM pdam_idx_accounts(NEW.id);
  RETURN NEW;
END $t$;
DROP TRIGGER IF EXISTS trg_idx_accounts ON accounts;
CREATE TRIGGER trg_idx_accounts AFTER INSERT OR UPDATE OR DELETE ON accounts
  FOR EACH ROW EXECUTE FUNCTION pdam_idx_trg_accounts();

CREATE OR REPLACE FUNCTION pdam_idx_jtrg_accounts() RETURNS trigger LANGUAGE plpgsql AS $j$
BEGIN
  PERFORM pdam_idx_accounts(COALESCE(NEW.accounts_id, OLD.accounts_id));
  RETURN NULL;
END $j$;
DROP TRIGGER IF EXISTS trg_idx_accounts_tags ON accounts_tags;
CREATE TRIGGER trg_idx_accounts_tags AFTER INSERT OR DELETE OR UPDATE ON accounts_tags
  FOR EACH ROW EXECUTE FUNCTION pdam_idx_jtrg_accounts();

